<section class="hero-card p-4 p-md-5">
  <div class="d-flex flex-wrap justify-content-between align-items-start gap-3 mb-4"><div><span class="badge text-bg-success-subtle mb-2">Organización</span><h1 class="h2 fw-bold mb-1">Categorías</h1><p class="text-secondary mb-0">Administra tus categorías de ingresos y gastos.</p></div><a class="btn btn-success" href="/categorias/nueva">Crear categoría</a></div>
  <?php if (!empty($success)): ?><div class="alert alert-success" role="status"><?= htmlspecialchars($success, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
  <?php if (!empty($error)): ?><div class="alert alert-danger" role="alert"><?= htmlspecialchars($error, ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?>
  <?php if (!$categories): ?><div class="text-center py-5"><h2 class="h5">Aún no tienes categorías</h2><p class="text-secondary">Crea una categoría para clasificar tus finanzas.</p><a href="/categorias/nueva" class="btn btn-outline-success">Crear la primera categoría</a></div>
  <?php else: ?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Tipo</th><th>Color</th><th>Uso</th><th class="text-end">Acciones</th></tr></thead><tbody>
  <?php foreach ($categories as $item): ?><tr><td class="fw-semibold"><?= htmlspecialchars($item['nombre'], ENT_QUOTES, 'UTF-8') ?></td><td><span class="badge <?= $item['tipo'] === 'ingreso' ? 'text-bg-success' : 'text-bg-warning' ?>"><?= $item['tipo'] === 'ingreso' ? 'Ingreso' : 'Gasto' ?></span></td><td><?php if ($item['color']): ?><span class="color-dot" style="background-color:<?= htmlspecialchars($item['color'], ENT_QUOTES, 'UTF-8') ?>"></span><?= htmlspecialchars($item['color'], ENT_QUOTES, 'UTF-8') ?><?php else: ?><span class="text-secondary">Sin color</span><?php endif; ?></td><td><?= (int) $item['movimientos'] ?> movimientos</td><td><div class="d-flex justify-content-end gap-2"><a class="btn btn-sm btn-outline-secondary" href="/categorias/editar?id=<?= (int) $item['id'] ?>">Editar</a><?php if ((int) $item['movimientos'] === 0): ?><form method="post" action="/categorias/eliminar" onsubmit="return confirm('¿Eliminar esta categoría?')"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf, ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) $item['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit">Eliminar</button></form><?php else: ?><button class="btn btn-sm btn-outline-danger" disabled title="Tiene movimientos asociados">Eliminar</button><?php endif; ?></div></td></tr><?php endforeach; ?>
  </tbody></table></div><?php endif; ?>
